-- Run in Supabase SQL Editor as project owner. Starts with blank operational records.
create extension if not exists pgcrypto;
do $$ begin create type public.app_role as enum ('admin','finance','coordinator','viewer'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role public.app_role not null default 'viewer',created_at timestamptz not null default now());
create table if not exists public.sponsors(id uuid primary key default gen_random_uuid(),name text not null,source text not null default 'Other',requested_amount numeric(12,2) not null default 0 check(requested_amount>=0),pledged_amount numeric(12,2) not null default 0 check(pledged_amount>=0),received_amount numeric(12,2) not null default 0 check(received_amount>=0),status text not null default 'Prospect',notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),title text not null,category text not null default 'Other',estimated_amount numeric(12,2) not null default 0 check(estimated_amount>=0),approved_amount numeric(12,2) not null default 0 check(approved_amount>=0),paid_amount numeric(12,2) not null default 0 check(paid_amount>=0),status text not null default 'Planned',date date,notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.tasks(id uuid primary key default gen_random_uuid(),title text not null,owner_name text,due_date date,priority text not null default 'Normal',status text not null default 'Open',notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.stations(id uuid primary key default gen_random_uuid(),name text not null unique check(name in ('FBMS','FAST A','FAST B','FOE','FBNE','FHAS')),agent_name text,coordinator_name text,agent_briefed boolean not null default false,supplies_checked boolean not null default false,transport_arranged boolean not null default false,notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create or replace function public.current_app_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
create or replace function public.has_any_role(allowed public.app_role[]) returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.current_app_role()=any(allowed),false) $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),'viewer') on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
-- Profiles: users can read their own profile; only admins can manage roles via SQL/project dashboard.
alter table public.profiles enable row level security; drop policy if exists profile_read on public.profiles; create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or public.has_any_role(array['admin']::public.app_role[]));
-- Shared read access for authenticated users; write permissions are role-based.
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['sponsors','expenses','tasks','stations'] LOOP EXECUTE format('alter table public.%I enable row level security',t); EXECUTE format('drop policy if exists signed_in_read on public.%I',t); EXECUTE format('create policy signed_in_read on public.%I for select to authenticated using (public.has_any_role(array[''admin'',''finance'',''coordinator'',''viewer'']::public.app_role[]))',t); END LOOP; END $$;
drop policy if exists sponsor_write on public.sponsors; create policy sponsor_write on public.sponsors for all to authenticated using(public.has_any_role(array['admin','finance']::public.app_role[])) with check(public.has_any_role(array['admin','finance']::public.app_role[]));
drop policy if exists expense_write on public.expenses; create policy expense_write on public.expenses for all to authenticated using(public.has_any_role(array['admin','finance']::public.app_role[])) with check(public.has_any_role(array['admin','finance']::public.app_role[]));
drop policy if exists task_write on public.tasks; create policy task_write on public.tasks for all to authenticated using(public.has_any_role(array['admin','coordinator']::public.app_role[])) with check(public.has_any_role(array['admin','coordinator']::public.app_role[]));
drop policy if exists station_write on public.stations; create policy station_write on public.stations for all to authenticated using(public.has_any_role(array['admin','coordinator']::public.app_role[])) with check(public.has_any_role(array['admin','coordinator']::public.app_role[]));
insert into public.stations(name) values('FBMS'),('FAST A'),('FAST B'),('FOE'),('FBNE'),('FHAS') on conflict(name) do nothing;
